(()=>{'use strict';const toggle=document.querySelector('.menu-toggle'),nav=document.querySelector('#mobile-nav');toggle.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')!=='true';toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Затворете менюто':'Отворете менюто');nav.hidden=!open});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!nav.hidden){nav.hidden=true;toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Отворете менюто');toggle.focus()}});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.hidden=true;toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Отворете менюто')}));window.matchMedia('(min-width:861px)').addEventListener('change',event=>{if(event.matches){nav.hidden=true;toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Отворете менюто')}});document.querySelectorAll('.quote-form').forEach(form=>{const select=form.elements.insurance,fields=form.querySelector('.go-fields'),result=form.querySelector('.form-result');function sync(){const active=['grazhdanska-otgovornost','kasko'].includes(select.value);fields.hidden=!active;fields.disabled=!active;fields.querySelector('legend').textContent=select.value==='kasko'?'Данни за Каско':'Данни за Гражданска отговорност';result.hidden=true}select.addEventListener('change',sync);sync();form.addEventListener('input',()=>result.hidden=true);form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;let summary=result.querySelector('.submitted-summary');if(!summary){summary=document.createElement('dl');summary.className='submitted-summary';result.prepend(summary)}summary.replaceChildren();const labels={insurance:'Застраховка',registration:'Регистрационен номер',engine:'Обем на двигателя (см³)',age:'Възраст на собственика',phone:'Телефон',message:'Съобщение'};for(const [key,value] of new FormData(form)){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=labels[key];dd.textContent=key==='insurance'?select.selectedOptions[0].textContent:value;summary.append(dt,dd)}result.hidden=false;result.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'nearest'})});form.querySelector('[data-download]').addEventListener('click',()=>{const data=new FormData(form);const labels={registration:'Регистрационен номер',engine:'Обем на двигателя (см³)',age:'Възраст на собственика',phone:'Телефон',message:'Съобщение'};let lines=['ЗАСТРАХОВКИ ГР.СТАМБОЛИЙСКИ - ПЛОВДИВ — ДЕМО ЗАПИТВАНЕ','Застраховка: '+select.selectedOptions[0].textContent];for(const [k,v] of data)if(labels[k])lines.push(labels[k]+': '+v);lines.push('','Демонстрация. Не е изпратено запитване.','За реална оферта: 089 597 0516.');const url=URL.createObjectURL(new Blob(['\uFEFF'+lines.join('\n')],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='sigurno-zapitvane.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)})})})();
(()=>{'use strict';const bar=document.querySelector('.mobile-call');if(!bar||!('IntersectionObserver'in window))return;const intro=document.querySelector('main section');const watched=[...document.querySelectorAll('a[href^="tel:+359"]:not(.mobile-call)'),...(intro?(intro.querySelector('.button,.claim-button')?intro.querySelectorAll('.button,.claim-button,.sub-link,.text-button'):[intro]):[])];const inView=new Set();bar.classList.add('is-resting');const observer=new IntersectionObserver(entries=>{entries.forEach(e=>e.isIntersecting?inView.add(e.target):inView.delete(e.target));bar.classList.toggle('is-resting',inView.size>0)});watched.forEach(el=>observer.observe(el));if(!watched.length)bar.classList.remove('is-resting')})();
